import unittest
from ascii_digits import *
class AsciiDigits(unittest.TestCase):
    def test_ascii_flag_and_entire_string(self):
        for text,expected in [('2048',True),('0',True),('0007',True),('１２３',False),('١٢٣',False),('12３',False),('12\n',False),('12 3',False),('',False),('+12',False)]:
            with self.subTest(text=text):
                self.assertIs(is_digits(text),expected)

if __name__ == '__main__':
    unittest.main()

